def states(L):
    return [tuple(_sage_const_1  - _sage_const_2 *((i >> j) & _sage_const_1 ) for j in range(L)) for i in range(_sage_const_2 **L)]

def h(s):
    LL = len(s)
    return sum(_sage_const_1  for j in range(LL) if s[j] != s[(j+_sage_const_1 ) % LL])

def v(s, t):
    return sum(_sage_const_1  for j in range(len(s)) if s[j] != t[j])

def Z_at(L, q):
    S = states(L)
    n = len(S)
    T = matrix(QQ, n, n, lambda i, j: q**(h(S[j]) + v(S[i], S[j])))
    return (T**L).trace()

